#include <cstdio>
#include <vector>
#include <algorithm>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    long long curMax = a[0], curMin = a[0], best = a[0];
    for (int i = 1; i < n; ++i) {
        long long x = a[i];
        long long c1 = x, c2 = curMax * x, c3 = curMin * x;
        curMax = std::max({c1, c2, c3});
        curMin = std::min({c1, c2, c3});
        best = std::max(best, curMax);
    }
    printf("%lld\n", best);
    return 0;
}
